    if (-not $configPath) {
        return [pscustomobject]@{
            ConfigPath               = $null
            alwaysOnSkills           = @('global-session-core')
            conditionalAlwaysOnSkills = @()
            promptKeywordBoosts    = @{}
            intentProfilesFile     = 'intent-profiles.json'
            intentMatchMinScore    = 3
