function Classify-UserMessageType {
    param([string]$UserPrompt)

    if ([string]::IsNullOrWhiteSpace($UserPrompt)) {
        return [pscustomobject]@{ Type = 'unknown'; Label = '未知'; ConsultationScore = 0; ImplementationScore = 0 }
    }

    $p = $UserPrompt.ToLowerInvariant()
    $consultSignals = @(
        '为什么', '为何', '怎么回事', '是不是', '会不会', '有哪些', '什么区别', '怎么工作', '如何工作',
        '什么意思', '解释', '说明一下', '原因', '根因', '为什么在你', '为什么没有', 'why', 'what are',
        'how does', 'explain', 'difference between', 'is it'
    )
    $implSignals = @(
        '帮我做', '帮我', '做一下', '改一下', '改一改', '实现', '开发', '加上', '优化一下', '整体优化',
        '修复', '修好', '部署', '写一个', '做一个', '重构', 'implement', 'build', 'fix', 'add feature',
        'refactor', 'create', 'ship'
    )

    $cScore = 0
    $iScore = 0
    foreach ($s in $consultSignals) { if ($p.Contains($s)) { $cScore += 2 } }
    foreach ($s in $implSignals) { if ($p.Contains($s)) { $iScore += 2 } }
    if ($p -match '[?？]\s*$') { $cScore += 3 }
    if ($p -match '(直接做|开始执行|按澄清|就改这一处)') { $iScore += 4 }

    $type = 'B'
    $label = '模糊实施（须完整澄清 §1–§12 + §7 待确认，禁止先 Write/Edit）'
    if ($iScore -eq 0 -and $cScore -ge 2) {
        $type = 'A'
        $label = '咨询/解释（轻量确认 1–2 句 + 直接回答；不须完整 §1–§12）'
    }
    elseif ($iScore -ge 4 -and $cScore -le 1) {
        $type = 'B'
        $label = '模糊实施（须完整澄清 §1–§12 + §7 待确认，禁止先 Write/Edit）'
    }
    elseif ($iScore -ge 2 -and $cScore -ge 2) {
        $type = 'B'
        $label = '咨询+隐含实施（先答问题，若涉及改代码须 §7 待确认后再动手）'
    }
    elseif ($iScore -ge 6) {
        $type = 'C'
        $label = '较清晰实施（§1 复述 + §12 极简；验收齐全可执行）'
    }

    return [pscustomobject]@{
        Type                = $type
        Label               = $label
        ConsultationScore   = $cScore
        ImplementationScore = $iScore
    }
}

