function Merge-PreToolUseMatcherBlock {
    param(
        [array]$ExistingBlocks,
        [string]$Matcher,
        [string]$Command,
        [int]$Timeout = 15,
        [string]$StatusMessage = 'Clarification hard gate'
    )

    $blocks = @()
    if ($ExistingBlocks) { $blocks = @($ExistingBlocks) }

    $already = $false
    foreach ($b in $blocks) {
        if ($b.matcher -eq $Matcher) {
            $hookList = @($b.hooks)
            $hasOurs = $false
            foreach ($h in $hookList) {
                if ($h.command -and $h.command.Contains('clarification-hard-gate.ps1')) { $hasOurs = $true }
            }
            if (-not $hasOurs) {
                $hookList += @{
                    type          = 'command'
                    command       = $Command
                    timeout       = $Timeout
                    statusMessage = $StatusMessage
                }
                $b.hooks = $hookList
            }
            $already = $true
            break
        }
    }
    if (-not $already) {
        $blocks += @{
            matcher = $Matcher
            hooks   = @(
                @{
                    type          = 'command'
                    command       = $Command
                    timeout       = $Timeout
                    statusMessage = $StatusMessage
                }
            )
        }
    }
    return $blocks
}

